WITH with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_burst FROM transactions), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT DATE_TRUNC('YEAR', txn_time) AS year_start, STDDEV_SAMP(amount) AS amount_stddev, COUNT(*) FILTER (WHERE merchant = 'Starbucks') AS starbucks_rows, PERCENTILE_APPROX(is_new_burst, 0.95) AS is_new_burst_p95, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list, MIN(txn_time) AS started_at, MAX(is_new_burst) AS max_is_new_burst, GROUPING_ID() AS grouping_level FROM islands GROUP BY ROLLUP (DATE_TRUNC('YEAR', txn_time)) HAVING PERCENTILE_APPROX(is_new_burst, 0.95) > 0 ORDER BY amount_stddev DESC;
